WITH grouped AS (SELECT *,CASE WHEN hours<=5.0/60 THEN 1 WHEN hours<=0.25 THEN 2 WHEN hours<=1 THEN 3 WHEN hours<=4 THEN 4 WHEN hours<=24 THEN 5 WHEN hours<=72 THEN 6 ELSE 7 END AS bucket FROM positions_usdt WHERE close_type!='部分平仓') SELECT bucket, CASE bucket WHEN 1 THEN '≤5分钟' WHEN 2 THEN '5–15分钟' WHEN 3 THEN '15–60分钟' WHEN 4 THEN '1–4小时' WHEN 5 THEN '4–24小时' WHEN 6 THEN '1–3天' ELSE '>3天' END AS "group", COUNT(*) AS n, SUM(gross) AS gross, SUM(fee) AS fee,SUM(gross+fee+funding+liquidation_fee) AS net FROM grouped GROUP BY bucket ORDER BY bucket;
